import {newState,DEFAULTS,CONTROL_DEFS} from './physics.js';
import {GENERIC_BOAT} from './boats.js';
import {PROFILE_FIELDS} from './sail-profiles.js';
export const SESSION_KEY='vento.session.v1';
const extra=['boat','sailDesigns','sailProfiles','fixedControls','fixedSheetLengths','sailOverlays'];
const copy=value=>JSON.parse(JSON.stringify(value));
export function snapshotState(state){state={...state,fixedSheetLengths:state.fixedSheetLengths||{},sailOverlays:state.sailOverlays||{}};return Object.fromEntries([...Object.keys(DEFAULTS),...extra].filter(key=>state[key]!==undefined).map(key=>[key,copy(state[key])]));}
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const finite=n=>typeof n==='number'&&Number.isFinite(n);
export function restoreSessionState(saved){if(!object(saved))return newState();let boat=GENERIC_BOAT;try{const b=saved.boat;if(object(b)&&typeof b.id==='string'&&typeof b.name==='string'&&['length','beam','draft','displacement'].every(k=>finite(b[k])&&b[k]>0)&&object(b.areas))boat=copy(b);const state=newState(boat);
 for(const [key,def]of Object.entries(DEFAULTS)){const value=saved[key];if(typeof def==='boolean'&&typeof value==='boolean')state[key]=value;else if(typeof def==='number'&&finite(value))state[key]=value;else if(typeof def==='string'&&typeof value==='string'&&value.length<200)state[key]=value;}
 if(!['economy','balanced','detailed'].includes(state.graphicsQuality))state.graphicsQuality='balanced';
 state.simulationResponse=Math.round(Math.max(-20,Math.min(20,state.simulationResponse)));state.windShear=Math.max(0,Math.min(.25,state.windShear));state.windSpeed=Math.max(0,Math.min(35,state.windSpeed));state.windAngle=Math.max(-180,Math.min(180,state.windAngle));state.reef=Math.max(0,Math.min(2,Math.round(state.reef)));state.genoaSize=Math.max(1,Math.min(500,state.genoaSize));state.forceScale=Math.max(.5,Math.min(2,state.forceScale));state.windDensity=Math.max(.5,Math.min(4,state.windDensity));state.windParticleScale=Math.max(.5,Math.min(2.5,state.windParticleScale));if(!/^#[0-9a-f]{6}$/i.test(state.windColor))state.windColor=DEFAULTS.windColor;if(!['none','genoa','spinnaker','gennaker'].includes(state.foresail))state.foresail='genoa';if(state.pressureScale!=='auto'&&!(Number(state.pressureScale)>0&&Number(state.pressureScale)<=100000))state.pressureScale='auto';
 for(const [cat,defs]of Object.entries(CONTROL_DEFS))for(const [key]of defs){const value=saved.controls?.[cat]?.[key];if(finite(value))state.controls[cat][key]=Math.max(0,Math.min(key==='twist'?50:cat==='genoa'&&key==='sheet'?120:100,value));const id=cat+'.'+key,lock=saved.fixedControls?.[id];if(key!=='twist'&&finite(lock)){state.fixedControls[id]=Math.max(0,Math.min(key==='twist'?50:100,lock));state.controls[cat][key]=state.fixedControls[id];}}
 state.fixedSheetLengths={};for(const type of ['main','genoa','spinnaker','gennaker']){const length=saved.fixedSheetLengths?.[type];if(finite(length)&&length>=0&&state.fixedControls[type+'.sheet']!==undefined)state.fixedSheetLengths[type]=length;const design=saved.sailDesigns?.[type];if(object(design)&&Object.keys(state.sailDesigns[type]).filter(k=>typeof state.sailDesigns[type][k]==='number').every(k=>finite(design[k])&&design[k]>0))state.sailDesigns[type]=copy(design);const profile=saved.sailProfiles?.[type];if(object(profile)&&Array.isArray(profile.stations)&&profile.stations.length>=2&&profile.stations.length<=65&&['crosscut','radial','membrane'].includes(profile.layout)&&finite(profile.stretch)&&profile.stretch>=0&&profile.stretch<=100&&finite(profile.weight)&&profile.weight>=25&&profile.weight<=600&&profile.stations.every((n,i,a)=>object(n)&&PROFILE_FIELDS.every(([key])=>finite(n[key]))&&Object.values(n).every(finite)&&n.h>=0&&n.h<=1&&(!i||n.h>a[i-1].h))&&profile.stations[0].h===0&&profile.stations.at(-1).h===1)state.sailProfiles[type]=copy(profile);}
 state.sailOverlays={};for(const type of ['main','genoa','spinnaker','gennaker'])if(typeof saved.sailOverlays?.[type]==='boolean')state.sailOverlays[type]=saved.sailOverlays[type];if(typeof saved.forceFocus==='string'&&saved.forceFocus.length<80)state.forceFocus=saved.forceFocus;
 for(const type of ['spinnaker','gennaker'])if(finite(saved.sailAreas?.[type])&&saved.sailAreas[type]>0)state.sailAreas[type]=saved.sailAreas[type];for(const key of Object.keys(state.forceGroups))if(typeof saved.forceGroups?.[key]==='boolean')state.forceGroups[key]=saved.forceGroups[key];return state;
 }catch{return newState();}}
function browserStorage(){try{return globalThis.window?.localStorage;}catch{return null;}}
export function readSession(storage=browserStorage()){try{const raw=storage?.getItem(SESSION_KEY);if(!raw||raw.length>1000000)return null;const value=JSON.parse(raw);if(value?.version!==1||!object(value.state))return null;return{state:restoreSessionState(value.state),ui:object(value.ui)?value.ui:{},runtime:object(value.runtime)?value.runtime:{}};}catch{return null;}}
export function createSessionPersistence({capture,storage=browserStorage(),onStatus=()=>{}}){let timer,last='',suppressed=false;function signature(value){return JSON.stringify([value.state,value.ui]);}function save(force=false){clearTimeout(timer);timer=null;try{const data=capture(),key=signature(data);if(!force&&key===last)return false;if(suppressed&&key===last)return false;storage?.setItem(SESSION_KEY,JSON.stringify({version:1,savedAt:new Date().toISOString(),...data}));last=key;suppressed=false;onStatus(storage?'saved':'unavailable');return!!storage;}catch{onStatus('unavailable');return false;}}
 return{schedule(){clearTimeout(timer);timer=setTimeout(()=>save(),350);},flush(){return save(true);},clear(){clearTimeout(timer);timer=null;try{for(const key of [SESSION_KEY,'vento.wind-appearance','vento.language'])storage?.removeItem(key);last=signature(capture());suppressed=true;onStatus('cleared');return true;}catch{onStatus('unavailable');return false;}},prime(){last=signature(capture());},cancel(){clearTimeout(timer);},read:()=>readSession(storage)};}
